<script setup>
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import AppSkeleton from "../../components/common/AppSkeleton.vue"
import AdminIcon from '../../components/admin/AdminIcon.vue'
import {ref,reactive,watch,inject} from 'vue'
import {useRoute} from 'vue-router'
import {useAuthStore} from '../../stores/auth'
import {branchesApi} from '../../api/branches.api'
import {deliveryZonesApi} from '../../api/delivery.api'
import {useApiState,useApiMutation} from '../../composables/useApiState'
import {normalizeApiError} from '../../utils/apiError'
import CatalogFields from '../../components/admin/catalog/CatalogFields.vue'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
import {formatCurrency} from '../../utils/formatters'
const auth=useAuthStore(),route=useRoute(),state=useApiState(),mutation=useApiMutation(),branches=ref([]),branch=ref(''),branchError=ref(null),branchLoading=ref(false),page=ref(1),showForm=ref(false),editing=ref(null),deleting=ref(null),confirmation=ref(null),districtText=ref('')
const {notify}=inject('admin')
const baseFields=[{key:'name',label:'اسم المنطقة',type:'text',required:true,max:150},{key:'type',label:'نوع المطابقة',type:'select',choices:[['district','الأحياء'],['radius','نطاق دائري']]},{key:'is_active',label:'منطقة نشطة',type:'checkbox'},{key:'delivery_fee',label:'رسوم التوصيل',type:'number',min:0,max:99999999.99,step:'0.01',required:true},{key:'minimum_order',label:'الحد الأدنى للطلب',type:'number',min:0,max:99999999.99,step:'0.01'},{key:'free_delivery_threshold',label:'حد التوصيل المجاني (اختياري)',type:'number',min:0,max:99999999.99,step:'0.01'},{key:'estimated_min_minutes',label:'مدة التوصيل الدنيا بالدقائق (اختياري)',type:'number',min:1,max:4294967295,step:1},{key:'estimated_max_minutes',label:'مدة التوصيل القصوى بالدقائق (اختياري)',type:'number',min:1,max:4294967295,step:1},{key:'priority',label:'الأولوية',type:'number',min:0,max:4294967295,step:1}]
const radiusFields=[{key:'center_latitude',label:'خط عرض المركز',type:'number',min:-90,max:90,step:'any',required:true},{key:'center_longitude',label:'خط طول المركز',type:'number',min:-180,max:180,step:'any',required:true},{key:'radius_km',label:'نصف القطر بالكيلومتر',type:'number',min:0.01,max:999999.99,step:'0.01',required:true}]
const blank=()=>({name:'',type:'district',is_active:true,delivery_fee:'',minimum_order:'0.00',free_delivery_threshold:'',estimated_min_minutes:'',estimated_max_minutes:'',priority:0,center_latitude:'',center_longitude:'',radius_km:''})
const recordLoading=ref(false),form=reactive(blank());let revision=0
async function loadBranches(){branchLoading.value=true;branchError.value=null;try{if(auth.can('branches.view')){let current=1,last=1,all=[];do{const result=await branchesApi.list({page:current,per_page:100});all.push(...result.data);last=result.meta.last_page;current++}while(current<=last);branches.value=all}else branches.value=await branchesApi.publicList();const requested=typeof route.query.branch==='string'?route.query.branch:'';branch.value=requested||branches.value[0]?.id||''}catch(cause){branchError.value=normalizeApiError(cause)}finally{branchLoading.value=false}}
function load(){if(branch.value)return state.run(signal=>deliveryZonesApi.list(branch.value,page.value,signal))}
watch(branch,()=>{revision++;showForm.value=false;editing.value=null;mutation.error.value=null;page.value=1;load()})
watch(page,load)
async function edit(record=null){const version=revision;mutation.error.value=null;if(record){recordLoading.value=true;let result;try{result=await mutation.run(()=>deliveryZonesApi.show(branch.value,record.id))}finally{recordLoading.value=false};if(!result.ok){if(mutation.error.value?.status===404)load();return}if(version!==revision)return;record=result.data}editing.value=record;Object.assign(form,blank(),record||{},record?.radius||{});districtText.value=(record?.districts||[]).join('\n');showForm.value=true}
async function save(){const version=revision,currentBranch=branch.value,body=Object.fromEntries(baseFields.map(field=>[field.key,form[field.key]]));for(const key of ['free_delivery_threshold','estimated_min_minutes','estimated_max_minutes'])if(body[key]==='')body[key]=null;for(const key of ['estimated_min_minutes','estimated_max_minutes','priority'])if(body[key]!=null)body[key]=Number(body[key]);if(form.type==='district')body.districts=districtText.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);else for(const field of radiusFields)body[field.key]=form[field.key]===''?null:Number(form[field.key]);const result=await mutation.run(()=>editing.value?deliveryZonesApi.update(currentBranch,editing.value.id,body):deliveryZonesApi.create(currentBranch,body));if(version!==revision)return;if(result.ok){showForm.value=false;notify('تم حفظ منطقة التوصيل.');load()}else if(mutation.error.value?.status===404)load()}
async function remove(){const version=revision;const result=await mutation.run(()=>deliveryZonesApi.remove(branch.value,deleting.value.id));confirmation.value.close();if(version!==revision)return;if(result.ok){notify('تم حذف منطقة التوصيل.');if(state.data.value?.data.length===1&&page.value>1)page.value--;else load()}else if(mutation.error.value?.status===404)load()}
async function toggle(item){const version=revision;const result=await mutation.run(()=>deliveryZonesApi.update(branch.value,item.id,{is_active:!item.is_active}));if(version!==revision)return;if(result.ok){notify('تم تحديث حالة المنطقة.');load()}else if(mutation.error.value?.status===404)load()}
loadBranches()
</script>
<template><main id="main"><AdminPageHeader class="page-heading"><div><span class="eyebrow">إدارة شيشلي</span><h1>مناطق التوصيل</h1><p>إدارة مناطق التوصيل ورسومها وأوقات الوصول.</p></div><button v-if="auth.can('delivery_zones.create')&&branch" class="button" :disabled="mutation.busy.value" @click="edit()"><AdminIcon name="plus"/> إضافة منطقة</button></AdminPageHeader><section class="panel"><div class="toolbar"><label class="field">الفرع<select v-model="branch" :disabled="branchLoading||mutation.busy.value"><option value="">اختر الفرع</option><option v-if="branch&&!branches.some(b=>b.id===branch)" :value="branch">الفرع المحدد</option><option v-for="item in branches" :key="item.id" :value="item.id">{{ item.name }}{{ item.is_active?'':' (متوقف)' }}</option></select></label></div><AppSkeleton v-if="recordLoading" variant="inline" label="جارٍ تحميل تفاصيل المنطقة…"/><ApiFeedback :loading="branchLoading||state.loading.value" :error="branchError||state.error.value" :empty="!!state.data.value&&!state.data.value.data.length" @retry="branchError?loadBranches():load()"/><div v-if="state.data.value?.data.length" class="table-wrap"><table v-admin-table><thead><tr><th>المنطقة / النوع</th><th>الحالة / الأولوية</th><th>النطاق</th><th>الرسوم / الحد الأدنى</th><th>توصيل مجاني / المدة</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="item in state.data.value.data" :key="item.id"><td><div class="admin-cell-value">{{ item.name }}<br>{{ item.type==='district'?'أحياء':'نطاق دائري' }}</div></td><td><div class="admin-cell-value"><span class="badge" :class="item.is_active?'good':'off'">{{ item.is_active?'نشطة':'متوقفة' }}</span><br>{{ item.priority }}</div></td><td><div class="admin-cell-value">{{ item.type==='district'?item.districts.join('، '):item.radius.radius_km+' كم' }}</div></td><td><div class="admin-cell-value">{{ formatCurrency(item.delivery_fee) }}<br>الحد الأدنى: {{ formatCurrency(item.minimum_order) }}</div></td><td><div class="admin-cell-value">{{ item.free_delivery_threshold==null?'بدون حد مجاني':formatCurrency(item.free_delivery_threshold) }}<br>{{ item.estimated_min_minutes??'غير محدد' }}–{{ item.estimated_max_minutes??'غير محدد' }} دقيقة</div></td><td><div class="admin-cell-value"><div class="admin-row-actions"><button class="row-button" :disabled="mutation.busy.value" @click="edit(item)">{{ auth.can('delivery_zones.update')?'تعديل / تفاصيل':'عرض التفاصيل' }}</button><button v-if="auth.can('delivery_zones.update')" class="row-button" :disabled="mutation.busy.value" @click="toggle(item)">{{ item.is_active?'تعطيل':'تفعيل' }}</button><button v-if="auth.can('delivery_zones.delete')" class="row-button danger" :disabled="mutation.busy.value" @click="deleting=item;confirmation.showModal()"><AdminIcon name="trash-2"/> حذف</button></div></div></td></tr></tbody></table></div><ApiPagination :meta="state.data.value?.meta" :links="state.data.value?.links" :busy="state.loading.value||mutation.busy.value" @page="page=$event"/><form v-if="showForm" class="catalog-subform" @submit.prevent="save"><h2>{{ editing?'تفاصيل منطقة التوصيل':'منطقة جديدة' }}</h2><CatalogFields :fields="baseFields" :form="form" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value||(editing&&!auth.can('delivery_zones.update'))"/><label v-if="form.type==='district'" class="field">الأحياء (حي في كل سطر)<textarea v-model="districtText" name="districts" rows="5" :disabled="mutation.busy.value||(editing&&!auth.can('delivery_zones.update'))" required/><small v-for="(messages,key) in mutation.error.value?.errors||{}" :key="key" class="field-error" v-show="key.startsWith('districts')">{{ messages.join(' ') }}</small></label><CatalogFields v-else :fields="radiusFields" :form="form" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value||(editing&&!auth.can('delivery_zones.update'))"/><p class="form-note">المطابقة بالأحياء تستخدم أسماء المدينة والحي بعد توحيدها على الخادم. النطاق الدائري يستخدم المسافة المباشرة، وليس مسافة القيادة. تغيير نوع المنطقة يستبدل إعدادات النوع السابق.</p><div class="form-actions"><button v-if="editing?auth.can('delivery_zones.update'):auth.can('delivery_zones.create')" class="button" :disabled="mutation.busy.value"><AdminIcon name="badge-check"/> حفظ</button><button type="button" class="row-button" :disabled="mutation.busy.value" @click="showForm=false">إغلاق</button></div></form><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/><dialog ref="confirmation" aria-labelledby="delete-zone-title"><h2 id="delete-zone-title">حذف منطقة التوصيل؟</h2><p>لن تُستخدم هذه المنطقة لمطابقة عناوين التوصيل بعد حذفها.</p><div class="form-actions"><button class="button danger" :disabled="mutation.busy.value" @click="remove">حذف المنطقة</button><button class="row-button" :disabled="mutation.busy.value" @click="confirmation.close()">إلغاء</button></div></dialog></section></main></template>

